public class Processor {
    public static void process(ProcessingElementsContainer container, ProcessingElement[] elements) {
        for (ProcessingElement element : elements) {
            if (element instanceof TypeProcessor) {
                ((TypeProcessor) element).process(container, element);
            } else if (element instanceof ElementProcessor) {
                ((ElementProcessor) element).process(container, element);
            }
        }
    }

    public static void testProcess(ProcessingElementsContainer container, ProcessingElement[] elements) {
        process(container, elements);
        boolean found = false;
        for (ProcessingElement element : elements) {
            if (element instanceof TypeProcessor || element instanceof ElementProcessor) {
                found = true;
                break;
            }
        }
        assert found == true;
    }

